import type { Page, Route } from "@playwright/test";
import { courseBackend, courseRoutes } from "./courseFixtures";
import { routeSecretFixture } from "./routeSecretHygiene";

// No request/response object survives the handler. Tests inspect public counters
// and redacted booleans; usernames/passwords are generated by the hygiene owner.
export async function studentBackend(page: Page) {
  const course = await courseBackend(page);
  course.grants = new Set(["courses.supervise"]);
  course.scopeIds = ["course_1"];
  course.courseState = "active";
  course.readiness = "active_not_accepting";
  course.activatedAt = "2026-10-10T10:00:00.000000Z";
  return studentRoutes(page, course);
}

// Install just the roster routes when another journey already owns the course
// and its capability handler. Do not register a second course fake on that page.
export async function studentRoutes(
  page: Page,
  course: Awaited<ReturnType<typeof courseRoutes>>,
) {
  const fixture = routeSecretFixture(page);
  const control = {
    course,
    posts: 0,
    valid: false,
    persisted: false,
    rosterReads: 0,
    membershipReads: 0,
    offsets: [] as number[],
    outcome: "success",
    denial: false,
    readFail: false,
    many: false,
    release: null as Promise<void> | null,
    forbiddenReads: 0,
  };
  const json = (route: Route, body: unknown, status = 200) =>
    route.fulfill({
      status,
      contentType: "application/vnd.api+json",
      headers: { "Cache-Control": "no-store" },
      body: JSON.stringify(body),
    });
  const fail = (route: Route, status: number, code: string) =>
    json(
      route,
      { errors: [{ status: String(status), code, detail: fixture.rawError }] },
      status,
    );
  const membership = (index = 1) => ({
    type: "course-students",
    id: `membership_${index}`,
    attributes: {
      username: index === 1 ? fixture.supervisorUsername : `learner.${index}`,
      joined_at: "2026-10-10T10:00:00.000000Z",
    },
    relationships: {
      course: { data: { type: "courses", id: "course_1" } },
      student: { data: { type: "users", id: `student_${index}` } },
    },
  });
  page.on("request", (request) => {
    const path = new URL(request.url()).pathname;
    if (
      /\/api\/v1\/(?:users(?:$|\/(?!me\/capabilities))|.*(?:transcripts|summaries|sessions|materials|avatars))/u.test(
        path,
      )
    )
      control.forbiddenReads++;
  });
  await page.route(
    /\/api\/v1\/courses\/course_1\/students(?:\?|$)/u,
    async (route) => {
      const request = route.request();
      if (request.method() === "POST") {
        control.posts++;
        control.valid =
          request.headers()["x-csrf-token"] === fixture.csrf &&
          request.headers()["accept"] === "application/vnd.api+json" &&
          request.headers()["content-type"] === "application/vnd.api+json" &&
          request.headers()["if-match"] === undefined &&
          JSON.stringify(request.postDataJSON()) ===
            JSON.stringify({
              data: {
                type: "course-students",
                attributes: {
                  mode: "provision",
                  username: fixture.supervisorUsername,
                  temporary_password: ` ${fixture.password} 密 `,
                  preferred_language: "de-DE",
                  country: "DE",
                  time_zone: "Europe/Berlin",
                },
              },
            });
        if (control.release) await control.release;
        if (control.denial) return fail(route, 404, "course_not_found");
        switch (control.outcome) {
          case "conflict":
            return fail(route, 409, "username_taken");
          case "invalid":
            return fail(route, 422, "course_student_invalid");
          case "inactive":
            return fail(route, 409, "course_invalid_state");
          case "csrf":
            return fail(route, 403, "csrf_invalid");
          case "expired":
            return fail(route, 401, "unauthorized");
          case "restricted":
            return fail(route, 403, "auth_password_change_required");
          case "server":
            return fail(route, 503, "unavailable");
        }
        control.persisted = true;
        if (control.outcome === "lose") return route.abort("failed");
        return json(
          route,
          control.outcome === "malformed"
            ? { data: null }
            : { data: membership() },
          201,
        );
      }
      control.rosterReads++;
      if (control.denial) return fail(route, 404, "course_not_found");
      if (control.readFail)
        return fail(route, 503, "course_readiness_unavailable");
      const query = new URL(request.url()).searchParams;
      const offset = Number(query.get("page[offset]"));
      control.offsets.push(offset);
      control.valid ||= query.size === 2 && query.get("page[limit]") === "25";
      const link = (next: number) =>
        `/api/v1/courses/course_1/students?page[limit]=25&page[offset]=${next}`;
      return json(route, {
        data: control.many
          ? Array.from({ length: offset === 0 ? 25 : 1 }, (_, index) =>
              membership(offset + index + 1),
            )
          : control.persisted
            ? [membership()]
            : [],
        meta: { has_more: control.many && offset === 0 },
        ...(control.many
          ? { links: offset === 0 ? { next: link(25) } : { prev: link(0) } }
          : {}),
      });
    },
  );
  await page.route("**/api/v1/courses/course_1/students/*", (route) => {
    control.membershipReads++;
    if (control.denial) return fail(route, 404, "course_student_not_found");
    const index = Number(
      new URL(route.request().url()).pathname.split("_").at(-1),
    );
    return json(route, { data: membership(index) });
  });
  return control;
}

export async function fillStudent(page: Page) {
  const fixture = routeSecretFixture(page);
  await page.locator("#student-username").fill(fixture.supervisorUsername);
  for (const id of ["new-password", "password-confirmation"])
    await page.locator(`#${id}`).fill(` ${fixture.password} 密 `);
  await page.locator("#student-language").selectOption("de-DE");
  await page.locator("#student-country").selectOption("DE");
  await page.locator("#student-time_zone").selectOption("Europe/Berlin");
}
